// Entrada: el agente envía el código a analizar en la variable "query"
const code = String(query || '');
const lines = code.split('\n');
const nonEmpty = lines.filter(l => l.trim() !== '');

// 1. Bucles y profundidad máxima de anidamiento (usando la indentación)
const loopRe = /^\s*(for|while)\b/;
let loops = 0;
let maxDepth = 0;
const stack = [];
for (const line of lines) {
  if (!line.trim()) continue;
  const indent = line.match(/^\s*/)[0].length;
  while (stack.length && stack[stack.length - 1] >= indent) stack.pop();
  if (loopRe.test(line)) {
    loops++;
    stack.push(indent);
    maxDepth = Math.max(maxDepth, stack.length);
  }
}

// 2. Recursión: funciones que se llaman a sí mismas
const defRe = /(?:def|function)\s+([A-Za-z_]\w*)|(?:const|let|var)\s+([A-Za-z_]\w*)\s*=\s*(?:function|\()/g;
const defs = [...code.matchAll(defRe)].map(m => ({ name: m[1] || m[2], declConParentesis: !!m[1] }));
const recursive = [];
for (const d of defs) {
  const total = (code.match(new RegExp('\\b' + d.name + '\\s*\\(', 'g')) || []).length;
  const calls = total - (d.declConParentesis ? 1 : 0);
  if (calls > 0) recursive.push({ funcion: d.name, llamadas_a_si_misma: calls });
}

// 3. ¿Hay memoización?
const memo = /memo|cache|lru_cache|new Map|dp\[/i.test(code);

// 4. Pista de complejidad temporal
let pista;
if (recursive.some(r => r.llamadas_a_si_misma >= 2) && !memo) pista = 'Recursión múltiple sin memoización: posible O(2^n)';
else if (recursive.length) pista = 'Recursión simple o memoizada: suele ser O(n) en tiempo y O(n) en pila';
else if (maxDepth >= 2) pista = `Bucles anidados (profundidad ${maxDepth}): posible O(n^${maxDepth})`;
else if (maxDepth === 1) pista = 'Un nivel de bucle: posible O(n)';
else pista = 'Sin bucles ni recursión: posible O(1)';

return JSON.stringify({
  lineas_de_codigo: nonEmpty.length,
  bucles: loops,
  anidamiento_maximo_bucles: maxDepth,
  funciones_recursivas: recursive,
  usa_memoizacion: memo,
  pista_complejidad: pista
}, null, 2);
